<?php
namespace App\Controllers; use App\Services\Database; use App\Services\View;
final class AuthController { public function showLogin(){View::render('auth/login',['title'=>'Login']);} public function showRegister(){View::render('auth/register',['title'=>'Create account']);} public function register(){\verify_csrf(); $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $pass=$_POST['password']??''; if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8||$pass!==($_POST['confirm_password']??'')) { $_SESSION['flash']='Please check your registration details.'; \redirect('/register'); } $db=Database::pdo(); $st=$db->prepare('INSERT INTO users(name,email,password_hash,email_verification_token,created_at) VALUES(?,?,?,?,NOW())'); $st->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),bin2hex(random_bytes(32))]); $_SESSION['user']=['id'=>$db->lastInsertId(),'name'=>$name,'email'=>$email]; \redirect('/dashboard'); } public function login(){\verify_csrf(); $db=Database::pdo(); $st=$db->prepare('SELECT * FROM users WHERE email=? AND deleted_at IS NULL'); $st->execute([strtolower(trim($_POST['email']??''))]); $u=$st->fetch(); if(!$u||!password_verify($_POST['password']??'',$u['password_hash'])){ sleep(1); $_SESSION['flash']='Invalid login.'; \redirect('/login'); } session_regenerate_id(true); $_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'email'=>$u['email']]; \redirect('/dashboard'); } public function logout(){ session_destroy(); \redirect('/'); } }
